# 1 lb = 453.59237 g and 1 oz = 28.349523125 g (international pound/ounce, exact definitions).
_GRAMS_PER_UNIT = {
    "g": 1.0,
    "kg": 1000.0,
    "lb": 453.59237,
    "oz": 28.349523125,
}

_WEIGHT_RE = re.compile(r"^(\d+(?:\.\d+)?)(g|kg|lb|oz)$")


def parse_weight(text: str) -> int:
    """Weight typed in by warehouse staff, as whole grams.

    Accepts an integer or a "."-separated decimal, then one of g, kg, lb or oz
    (case-insensitive), with optional whitespace around it. Raises ValueError
    for anything else, including missing numbers or units and negative values.
    """
    if not isinstance(text, str):
        raise ValueError(f"expected a weight string, got {type(text).__name__}")
    match = _WEIGHT_RE.fullmatch(text.strip().lower())
    if not match:
        raise ValueError(f"invalid weight: {text!r}")
    value = float(match.group(1))
    return round(value * _GRAMS_PER_UNIT[match.group(2)])
